import { parseFormula } from './parse.js'
import { Sheet, format } from './eval.js'
import { parseAddr, colIndex } from './addr.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const stripped = lines[i].replace(/^[ \t]+/, '')
  if (stripped === '' || stripped[0] === '#') continue
  const m = /^[^ \t]*/.exec(stripped)
  const raw = m[0]
  const addr = raw.toUpperCase()
  const rest = stripped.slice(raw.length).replace(/^[ \t]/, '').replace(/^[ \t]*/, '')
  const p = parseAddr(addr)
  if (!p) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${addr}\n`)
    process.exit(2)
  }
  if (cells.has(addr)) {
    process.stderr.write(`error: line ${i + 1}: cell ${addr} is declared twice\n`)
    process.exit(2)
  }
  cells.set(addr, { addr, col: p.col, row: p.row, content: rest })
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
const out = []
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of sorted) out.push(`${c.addr}=${format(sheet.valueOf(c.addr))}\n`)
} else {
  for (const c of sorted) {
    const names = new Set()
    if (c.content.startsWith('=')) {
      const r = parseFormula(c.content.slice(1))
      if (r.ok) collect(r.node, names)
    }
    const list = [...names].map((a) => parseAddr(a)).sort((a, b) => a.col - b.col || a.row - b.row)
    out.push(`${c.addr}:${list.map((p) => ' ' + p.name).join('')}\n`)
  }
}
process.stdout.write(out.join(''))

function collect(n, set) {
  switch (n.type) {
    case 'ref': {
      const p = parseAddr(n.name)
      if (p) set.add(p.name)
      break
    }
    case 'range': {
      const a = parseAddr(n.a)
      const b = parseAddr(n.b)
      if (a && b) {
        for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
          for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) set.add(colName(c) + r)
      }
      break
    }
    case 'call':
      n.args.forEach((x) => collect(x, set))
      break
    case 'paren':
    case 'unary':
      collect(n.x, set)
      break
    case 'bin':
      collect(n.l, set)
      collect(n.r, set)
      break
  }
}

function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}
