{"file_path":"src/addr.js","content":"export function colIndex(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 64
  return 27 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 65)
}

// Returns {col,row,name} for an in-range address (any case), else null.
export function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  return { col: colIndex(letters), row, name: letters + row }
}
"}

