{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'
import { parseAddr } from './addr.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const num = (v) => ({ t: 'n', v })
const err = (v) => ({ t: 'e', v })
const isErr = (x) => x.t === 'e'

export function format(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    case 's': return v.v
    default: return v.v
  }
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}
function finite(x) {
  return Number.isFinite(x) ? num(x) : err('#DIV/0!')
}
function cmpStr(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const rank = { n: 0, s: 1, b: 2 }
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'n') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 's') return cmpStr(a.v, b.v)
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.stack = new Set()
    this.parsed = new Map()
  }

  valueOf(addr) {
    if (this.memo.has(addr)) return this.memo.get(addr)
    const cell = this.cells.get(addr)
    if (!cell) return num(0)
    if (this.stack.has(addr)) return err('#CYCLE!')
    this.stack.add(addr)
    let v
    try {
      v = this.compute(cell.content)
    } finally {
      this.stack.delete(addr)
    }
    this.memo.set(addr, v)
    return v
  }

  compute(content) {
    if (content.startsWith('=')) {
      const r = parseFormula(content.slice(1))
      if (!r.ok || r.misplaced) return err('#ERR!')
      return this.ev(r.node)
    }
    if (content === '') return num(0)
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
    if (ERRORS.includes(content)) return err(content)
    return { t: 's', v: content }
  }

  ref(name) {
    const p = parseAddr(name)
    if (!p) return err('#REF!')
    return this.valueOf(p.name)
  }

  ev(n) {
    switch (n.type) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'ref': return this.ref(n.name)
      case 'paren': return this.ev(n.x)
      case 'range': return err('#ERR!')
      case 'unary': {
        const x = this.ev(n.x)
        if (isErr(x)) return x
        const v = toNum(x)
        if (isErr(v)) return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.ev(n.l)
    if (isErr(l)) return l
    const r = this.ev(n.r)
    if (isErr(r)) return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
