  const stripped = lines[i].replace(/^[ \t]+/, '')
  if (stripped === '' || stripped[0] === '#') continue
  const m = /^[^ \t]*/.exec(stripped)
  const raw = m[0]
  const addr = raw.toUpperCase()
  const rest = stripped.slice(raw.length).replace(/^[ \t]/, '').replace(/^[ \t]*/, '')
  const p = parseAddr(addr)
  if (!p) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${addr}\n`)
    process.exit(2)
  }
  if (cells.has(addr)) {
    process.stderr.write(`error: line ${i + 1}: cell ${addr} is declared twice\n`)
    process.exit(2)
  }
  cells.set(addr, { addr, col: p.col, row: p.row, content: rest })
