  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    if (s.startsWith('<=', i) || s.startsWith('>=', i) || s.startsWith('<>', i)) {
      toks.push({ k: 'op', v: s.slice(i, i + 2) }); i += 2; continue
    }
    if ('^*/+-=<>(),:'.includes(ch)) { toks.push({ k: 'op', v: ch }); i++; continue }
