  const expect = (v) => { if (!peek(v)) throw new Fail(); pos++ }

  function cmp() {
    let l = add()
    while (pos < toks.length && toks[pos].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[pos].v)) {
      const op = toks[pos++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (peek('+') || peek('-')) {
      const op = toks[pos++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (peek('*') || peek('/')) {
      const op = toks[pos++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (peek('^')) { pos++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (peek('-') || peek('+')) {
      const op = toks[pos++].v
      return { type: 'unary', op, x: unary() }
    }
    return primary()
  }
  function primary() {
    if (pos >= toks.length) throw new Fail()
    const t = toks[pos]
    if (t.k === 'num') { pos++; return { type: 'num', v: Number(t.v) } }
    if (t.k === 'op' && t.v === '(') {
      pos++
      const x = cmp()
      expect(')')
      return { type: 'paren', x }
    }
    if (t.k === 'word') {
      pos++
      if (peek('(')) {
        pos++
        const args = []
        if (!peek(')')) {
          for (;;) {
            args.push(arg())
            if (peek(',')) { pos++; continue }
            break
          }
        }
        expect(')')
        return { type: 'call', name: t.v.toUpperCase(), args }
      }
      if (peek(':')) {
        pos++
        if (pos >= toks.length || toks[pos].k !== 'word') throw new Fail()
        misplaced = true
        return { type: 'range', a: t.v, b: toks[pos++].v }
      }
