      toks[pos + 2].k === 'word' &&
      pos + 3 < toks.length && toks[pos + 3].k === 'op' && (toks[pos + 3].v === ',' || toks[pos + 3].v === ')')
    ) {
      const n = { type: 'range', a: toks[pos].v, b: toks[pos + 2].v }
      pos += 3
      return n
    }
    return cmp()
  }

  try {
    const node = cmp()
    if (pos !== toks.length) return { ok: false }
    return { ok: true, node, misplaced }
  } catch (e) {
    if (e instanceof Fail) return { ok: false }
    throw e
  }
}
